using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer supports mutable
        // values like DateTime.UtcNow. Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB Context (separate project) ---
// Demonstrates fixes for EF Core 9 Cosmos breaking changes.

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");

            // Breaking change #1: EF Core 9 renamed the discriminator property
            // from "Discriminator" to "$type". For existing documents that already
            // store "Discriminator", explicitly configure the old property name.
            b.HasDiscriminator<string>("Discriminator");
        });
    }

    // Breaking change #2: EF Core 9 removed synchronous Cosmos DB query APIs.
    // All queries must now use async (ToListAsync, FirstOrDefaultAsync, etc.).
    public async Task<List<Product>> GetProductsAsync()
    {
        // BEFORE (EF Core 8 - no longer compiles):
        //   return Products.ToList();
        //
        // AFTER (EF Core 9 - async required):
        return await Products.ToListAsync();
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

